import{R as e,e as a,f as o,U as n}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"hCaptcha","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/hcaptcha.md","filePath":"integrations/captchas/hcaptcha.md","lastUpdated":1775908585000}'),r={name:"integrations/captchas/hcaptcha.md"};function s(h,t,i,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="hcaptcha" tabindex="-1">hCaptcha <a class="header-anchor" href="#hcaptcha" aria-label="Permalink to &quot;hCaptcha&quot;">​</a></h1><p>Follow the below steps to connect Formie to hCaptcha.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>hCaptcha</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-hcaptcha-keys" tabindex="-1">Step 2. Get your hCaptcha Keys <a class="header-anchor" href="#step-2-get-your-hcaptcha-keys" aria-label="Permalink to &quot;Step 2. Get your hCaptcha Keys&quot;">​</a></h3><ol><li>Go to the <a href="https://dashboard.hcaptcha.com/" target="_blank" rel="noreferrer">hCaptcha dashboard</a> and sign in to your account.</li><li>Open the <strong>Sites</strong> tab and create a new sitekey.</li><li>Open the <strong>Settings</strong> tab and generate your secret key.</li><li>Copy the <strong>Site Key</strong> and <strong>Secret Key</strong>.</li></ol><h3 id="step-3-connect-formie-to-hcaptcha" tabindex="-1">Step 3. Connect Formie to hCaptcha <a class="header-anchor" href="#step-3-connect-formie-to-hcaptcha" aria-label="Permalink to &quot;Step 3. Connect Formie to hCaptcha&quot;">​</a></h3><ol><li>Paste the <strong>hCaptcha Site Key</strong> into the <strong>hCaptcha Site Key</strong> field in Formie.</li><li>Paste the <strong>hCaptcha Secret Key</strong> into the <strong>hCaptcha Secret Key</strong> field in Formie.</li><li>Choose the front-end options you want, such as <strong>Theme</strong>, <strong>Size</strong>, <strong>Minimum Score</strong>, <strong>Language</strong>, and <strong>Script Loading Method</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>hCaptcha</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the captcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>hCaptcha supports visible and invisible modes. The <strong>Size</strong> setting in Formie controls which mode is rendered for the form.</p>',11)])])}const m=e(r,[["render",s]]);export{d as __pageData,m as default};
